def forward(groups):
    size = float(groups[0])
    unit = groups[1]
    multiplier = {'B': 1, 'KB': 1024, 'MB': 1024**2, 'GB': 1024**3}[unit]
    return {'stored': [int(round(size * multiplier))], 'layout': [unit]}

def inverse(record):
    size_in_bytes = record['stored'][0]
    unit = record['layout'][0]
    multiplier = {'B': 1, 'KB': 1024, 'MB': 1024**2, 'GB': 1024**3}[unit]
    return f"{size_in_bytes / multiplier:.1f} {unit}"
